/*
 * Firmware-owned storage of one Axon model slot, compiled once per slot by
 * model_ota_axon_add_app_stub(). A model image binds to these symbols, so they must stay in the
 * firmware even though the firmware itself does not compile the model.
 *
 * The Axon model header is not included: it declares the persistent-vars array with the size
 * the model requires, while the slot may provide more.
 */

#include <stdint.h>

/* Slot capacities and storage symbols, generated by axon_elf.py inspect. */
#include "model_ota_axon_model_config.h"

#if !defined(MODEL_OTA_AXON_CONFIG_VERSION) || (MODEL_OTA_AXON_CONFIG_VERSION != 0)
#error "Unsupported or missing Axon model configuration"
#endif

const int8_t *MODEL_OTA_AXON_INPUT_VECTOR_LIST_SYM[MODEL_OTA_AXON_INPUT_VECTOR_CAP];

#if MODEL_OTA_AXON_PERSISTENT_VARS_REQUIRED > 0
#if MODEL_OTA_AXON_PERSISTENT_VARS_REQUIRED > MODEL_OTA_AXON_PERSISTENT_VARS_CAP
#error "MODEL_OTA_AXON_PERSISTENT_VARS_CAP is smaller than what the model requires"
#endif

int32_t MODEL_OTA_AXON_PERSISTENT_VARS_SYM[MODEL_OTA_AXON_PERSISTENT_VARS_CAP];
#endif

#if MODEL_OTA_AXON_PACKED_OUTPUT_ALLOC
uint32_t MODEL_OTA_AXON_PACKED_OUTPUT_SYM[MODEL_OTA_AXON_PACKED_OUTPUT_BYTES / sizeof(uint32_t)];
#endif
